return $input.all().filter(i => i.json && i.json.name).map(i => ({ json: {
  repo: i.json.name, default_branch: i.json.default_branch || 'main'
}}));

const map = {};
for (const it of $input.all()) {
  const j = it.json;
  if (!j || !j.repo) continue;
  map[j.repo] = { locales: j.locales || [], roots: j.roots || {} };
}
return [{ json: { map: map, repo_count: Object.keys(map).length } }];

const r = $input.first().json || {};
const body = r.body || {};
if (!Array.isArray(body.projects)) throw new Error('No projects array. Status ' + r.statusCode);

const DROP = [/html/i, /legal/i, /shared/i, /multiproject/i, /myevisa/i, /visahub/i, /^marketing$/i, /demo/i];
return body.projects
  .filter(p => !DROP.some(rx => rx.test(p.name || '')))
  .map(p => ({ json: { project_id: p.project_id, name: p.name } }));

const PROJECT_TO_REPO = {
  'Personality.co': 'personality-app::src/locale',
  'Personality - Members area content': 'personality-app::src/locale-members',
  'Chat AI - frontend': 'aichat-frontend',
  'Chat AI (emails)': 'aichat-backend',
  'Chatbot': 'chatbot-backend',
  'Realchecker (FE)': 'realchecker-frontend',
  'Realchecker (BE)': 'realchecker-backend',
  'Mobitrace': 'mobitrace-frontend',
  'Mobitrace - backend/emails': 'mobitrace-backend',
  'My Image': 'myimage-frontend',
  'My Image - Backend': 'myimage-backend',
  'WAPP': 'mywapp-frontend',
  'WAPP Backend (emails)': 'mywapp-backend',
  'PDF Editor': 'pdfhelp-frontend',
  'PDF Editor (BE- emails)': 'pdfhelp-backend',
  'PDF Editor monorepo': 'pdfhelp-monorepo',
  'My QR Code': 'qr-frontend',
  'VIN Checker': 'vinchecker-frontend',
  'ResumeWise': 'resumewise-frontend',
  'ResumeWise - backend/emails': 'resumewise-backend',
  'Love Language - Static': 'lovelanguage-frontend',
  'Love Language  - Members areas DEV': 'lovelanguage-backend',
  'Mindspree': 'mindspree-app',
  'IQ test': 'iqtest-monorepo',
  'BrainIQ Test': 'iqtest-monorepo',
  'Unicopy': 'aichecker-frontend',
  'Unicopy (backend)': 'aichecker-app'
