const PROJECT_TO_PRODUCT = {
  'Chat AI - frontend': 'Chat AI',
  'Chat AI (emails)': 'Chat AI',
  'Chatbot': 'Chatbot',
  'IQ test': 'IQ Test',
  'BrainIQ Test': 'IQ Test',
  'Love Language - Static': 'Love Language',
  'Love Language  - Members areas DEV': 'Love Language',
  'Mindspree': 'Mindspree',
  'Mobitrace': 'Mobitrace',
  'Mobitrace - backend/emails': 'Mobitrace',
  'My Image': 'My Image',
  'My Image - Backend': 'My Image',
  'My QR Code': 'My QR Code',
  'PDF Editor': 'PDF Editor',
  'PDF Editor (BE- emails)': 'PDF Editor',
  'PDF Editor monorepo': 'PDF Editor',
  'Personality.co': 'Personality',
  'Personality - Members area content': 'Personality',
  'QRcreate': 'QRcreate',
