};

const repoData = $('Repo Map').first().json.map || {};
const rows = $input.all().map(i => i.json).filter(r => r.http_status === 200);

function repoLocales(spec) {
  if (!spec) return null;
  const [repo, root] = spec.split('::');
  const entry = repoData[repo];
  if (!entry) return null;
  if (root) return entry.roots[root] || [];
  return entry.locales || [];
}

const supported = [];
const notInCode = [];

for (const r of rows) {
  const spec = PROJECT_TO_REPO[r.name] || null;
  const rl = repoLocales(spec);
  const lokSet = r.targets.map(t => t.iso);
  const base = {
    product: PROJECT_TO_PRODUCT[r.name] || r.name,
    project: r.name,
    language_count: r.target_count,
    locales: r.targets.map(t => t.progress < 100 ? t.iso + ' (' + t.progress + '%)' : t.iso).join(' ') || '-',
    progress: r.avg_progress,
    repo: spec ? spec.replace('::', ' / ') : '-'
  };

  if (!rl) {
    notInCode.push(Object.assign({}, base, { missing: 'No repo identified', missing_count: null }));
    continue;
  }

  const rset = rl.filter(l => l !== 'en');
  const notInRepo = lokSet.filter(l => !rset.includes(l));
  const notInLok = rset.filter(l => !lokSet.includes(l));

  if (notInRepo.length) {
    notInCode.push(Object.assign({}, base, { missing: notInRepo.join(' '), missing_count: notInRepo.length }));
  } else {
    supported.push(Object.assign({}, base, {
      note: notInLok.length ? 'in code but not in Lokalise: ' + notInLok.join(' ') : 'match'
    }));
  }
}

function byProduct(a, b) {
  return a.product.localeCompare(b.product, 'en', { sensitivity: 'base' })
      || a.project.localeCompare(b.project, 'en', { sensitivity: 'base' });
}
supported.sort(byProduct);
notInCode.sort(byProduct);

function esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function table(head, list, lastCol) {
  let h = '<table><tbody><tr>' + head.map(x => '<th>' + x + '</th>').join('') + '</tr>';
  let prev = null;
  for (const o of list) {
    const first = o.product !== prev;
    prev = o.product;
    h += '<tr>' +
      '<td>' + (first ? '<strong>' + esc(o.product) + '</strong>' : '') + '</td>' +
      '<td>' + esc(o.project) + '</td>' +
      '<td>' + o.language_count + '</td>' +
      '<td>' + esc(o.locales) + '</td>' +
      '<td>' + o.progress + '%</td>' +
      '<td>' + esc(o.repo) + '</td>' +
      '<td>' + esc(lastCol(o)) + '</td>' +
    '</tr>';
  }
  return h + '</tbody></table>';
}

let html = '<p>Generated ' + new Date().toISOString().slice(0,10) + ' from Lokalise and the QR-CODE-App GitHub org. Excludes html/legal, shared, demo and internal projects.</p>';
html += '<h2>Localization status</h2>';
html += table(['Product','Project','Languages','Locales','Completed','Repo','Notes'], supported, o => o.note);
html += '<h2>Not yet supported in the code</h2>';
html += '<p>Translated in Lokalise but the locale files are absent from the repository, so these languages cannot ship.</p>';
html += table(['Product','Project','Languages','Locales','Completed','Repo','Missing from repo'], notInCode,
  o => o.missing_count ? o.missing_count + ': ' + o.missing : o.missing);

return [{ json: {
  generated_at: new Date().toISOString(),
  repos_scanned: Object.keys(repoData).length,
  supported_count: supported.length,
  not_in_code_count: notInCode.length,
  supported: supported,
  not_in_code: notInCode,
  html: html
}}];

const meta = $('Lokalise Loop').first().json;
const r = $input.first().json || {};
const body = r.body || {};
const st = body.statistics || {};
const qa = st.qa_issues || {};
const EXCLUDE = new Set(['ps', 'pst', 'cus', 'pt_old']);

const base = body.base_language_iso || 'en';
const targets = (Array.isArray(st.languages) ? st.languages : [])
  .filter(l => !EXCLUDE.has(l.language_iso) && l.language_iso !== base)
  .map(l => ({ iso: l.language_iso, progress: l.progress }))
  .sort((a,b) => a.iso.localeCompare(b.iso));

const avg = targets.length ? Math.round(targets.reduce((s,l) => s + l.progress, 0) / targets.length) : 0;

return [{ json: {
  project_id: meta.project_id,
  name: body.name || meta.name,
  http_status: r.statusCode,
  base_iso: base,
  target_count: targets.length,
  avg_progress: avg,
  not_reviewed: qa.not_reviewed || 0,
  unverified: qa.unverified || 0,
  targets: targets
}}];

const meta = $('GH Loop').first().json;
const res = $input.first().json || {};
const body = res.body || {};
const tree = Array.isArray(body.tree) ? body.tree : [];

const LOCALE_DIR = /^(locales?|i18n|lang|langs|languages|messages|translations?|intl)([-_][a-z0-9]+)?$/i;
const EXT = /\.(json|ts|tsx|js|mjs|cjs|ya?ml|po|pot|mo|properties|xlf|xliff|arb|strings|resx)$/i;
const ISO = new Set(('aa ab ae af ak am an ar as av ay az ba be bg bh bi bm bn bo br bs ca ce ch co cr cs cu cv cy ' +
 'da de dv dz ee el en eo es et eu fa ff fi fj fo fr fy ga gd gl gn gu gv ha he hi ho hr ht hu hy hz ia id ie ig ' +
 'ii ik io is it iu ja jv ka kg ki kj kk kl km kn ko kr ks ku kv kw ky la lb lg li ln lo lt lu lv mg mh mi mk ml ' +
 'mn mr ms mt my na nb nd ne ng nl nn no nr nv ny oc oj om or os pa pi pl ps pt qu rm rn ro ru rw sa sc sd se sg ' +
 'si sk sl sm sn so sq sr ss st su sv sw ta te tg th ti tk tl tn to tr ts tt tw ty ug uk ur uz ve vi vo wa wo xh ' +
 'yi yo za zh zu fil ceb haw kab pst cus').split(/\s+/));
const SKIP = new Set(['ps', 'pst', 'cus', 'pt_old', 'pt_BR']);

function isLocaleToken(tok) {
  const t = String(tok).toLowerCase();
  const m = t.match(/^([a-z]{2,3})(?:[-_]([a-z]{2,4}))?$/);
  if (!m) return null;
  if (!ISO.has(m[1])) return null;
  return m[2] ? m[1] + '_' + m[2].toUpperCase() : m[1];
}

const all = {};
const roots = {};
for (const n of tree) {
  if (n.type !== 'blob') continue;
  const p = n.path;
  if (!p) continue;
  if (/(^|\/)(node_modules|dist|build|\.next|vendor|coverage)(\/|$)/i.test(p)) continue;
  const parts = p.split('/');
  let idx = -1;
  for (let i = 0; i < parts.length - 1; i++) if (LOCALE_DIR.test(parts[i])) idx = i;
  if (idx === -1) continue;
  const rest = parts.slice(idx + 1);
  if (!rest.length) continue;
  let cand = rest[0];
  if (rest.length === 1) {
    if (!EXT.test(cand)) continue;
    cand = cand.replace(EXT, '');
  }
  const loc = isLocaleToken(cand);
  if (!loc || SKIP.has(loc)) continue;
  all[loc] = true;
  const root = parts.slice(0, idx + 1).join('/');
  roots[root] = roots[root] || {};
  roots[root][loc] = true;
}

const rootMap = {};
for (const r of Object.keys(roots)) rootMap[r] = Object.keys(roots[r]).sort();

return [{ json: { repo: meta.repo, locales: Object.keys(all).sort(), roots: rootMap } }];
